#include "motion_archive.h"
#include "archive_csv.h"
namespace rs3d {
namespace {
void require(bool b,const char*m){if(!b)throw std::runtime_error(m);}
Vec3 vector(const CsvRow&r,const std::string&p){return {archiveNumber(r.at(p+"x")),archiveNumber(r.at(p+"y")),archiveNumber(r.at(p+"z"))};}
Quaternion rotation(const CsvRow&r){Quaternion q{archiveNumber(r.at("qw")),archiveNumber(r.at("qx")),archiveNumber(r.at("qy")),archiveNumber(r.at("qz"))};double length=q.w*q.w+q.x*q.x+q.y*q.y+q.z*q.z;require(std::abs(length-1)<.01,"invalid legacy quaternion");return q;}
StopReason reason(const std::string&s){for(int i=0;i<=int(StopReason::cancelled);++i)if(s==stopReasonName(StopReason(i)))return StopReason(i);throw std::runtime_error("unknown legacy stop reason");}
}
std::shared_ptr<const MotionDirectory> readLegacyMotionDirectory(const std::filesystem::path&path,std::uint64_t n){
    require(n>0&&n<=1000000,"legacy directory capacity exceeded");auto directory=std::make_shared<MotionDirectory>();directory->location=std::make_shared<ArchiveLocation>(path);directory->legacy=true;std::vector<std::shared_ptr<MotionTrial>> trials;for(std::uint64_t id=1;id<=n;++id){auto t=std::make_shared<MotionTrial>();t->id=id;t->status="not_recorded";trials.push_back(t);}
    std::uint64_t previousId=0;
    if(std::filesystem::exists(path/"trajectory.csv"))scanArchiveCsv(path/"trajectory.csv",size_t(n)*100000,[&](const CsvRow&r,std::uint64_t offset,std::uint64_t length){auto id=archiveInteger(r.at("trial_id"));require(id>0&&id<=n&&id>=previousId,"legacy trajectory trial order");previousId=id;auto&t=*trials[size_t(id-1)];double time=archiveNumber(r.at("time"));require(time>=0&&(!t.frames||time>t.lastTime),"legacy times not strictly increasing");
        if(t.blocks.empty()||t.blocks.back().frames==motionBlockFrames){MotionBlock b;b.trialId=id;b.offset=offset;b.firstTime=time;b.firstStep=t.frames;t.blocks.push_back(b);}auto&b=t.blocks.back();require(offset==b.offset+b.length,"noncontiguous legacy block");b.length+=length;++b.frames;b.lastTime=time;b.lastStep=t.frames;if(!t.frames)t.firstTime=time;++t.frames;t.lastTime=time;t.status=r.at("reason");reason(t.status);});
    if(std::filesystem::exists(path/"barrier_trajectory.csv")){std::vector<std::uint64_t> counts(size_t(n),0);std::uint64_t total=0;scanArchiveCsv(path/"barrier_trajectory.csv",size_t(n)*100000,[&](const CsvRow&r,std::uint64_t offset,std::uint64_t length){auto id=archiveInteger(r.at("trial_id"));require(id>0&&id<=n,"legacy barrier trial outside directory");auto&t=*trials[size_t(id-1)];auto&count=counts[size_t(id-1)];require(count<t.frames,"legacy barrier/rock frame count mismatch");auto&b=t.blocks[size_t(count/motionBlockFrames)];auto index=count%motionBlockFrames;auto time=archiveNumber(r.at("time"));if(index==0){require(time==b.firstTime,"legacy barrier start time mismatch");b.legacyBarrierOffset=offset;}if(index+1==b.frames)require(time==b.lastTime,"legacy barrier end time mismatch");require(offset==b.legacyBarrierOffset+b.legacyBarrierLength,"noncontiguous legacy barrier block");b.legacyBarrierLength+=length;++count;++total;});if(total){for(size_t i=0;i<trials.size();++i)require(counts[i]==trials[i]->frames,"legacy dynamic barrier history incomplete");directory->legacyBarrier=true;}}
    for(auto&t:trials)directory->trials.push_back(t);directory->version=1;return directory;
}
std::vector<MotionFrame> readLegacyMotionBlock(const MotionDirectory&d,const MotionBlock&b){
    std::vector<MotionFrame> frames;readArchiveCsvRange(d.location->path()/"trajectory.csv",b.offset,b.length,motionBlockFrames,[&](const CsvRow&r){require(archiveInteger(r.at("trial_id"))==b.trialId,"legacy block trial mismatch");MotionFrame f;f.step=b.firstStep+frames.size();auto&s=f.snapshot;s.time=archiveNumber(r.at("time"));s.center=vector(r,"com_");s.shapeOrigin=vector(r,"origin_");s.rotation=rotation(r);s.velocity=vector(r,"v");s.angularVelocity=vector(r,"omega_");s.reason=reason(r.at("reason"));if(!frames.empty())require(s.time>frames.back().snapshot.time,"legacy block time order");frames.push_back(f);});require(frames.size()==b.frames&&!frames.empty()&&frames.front().snapshot.time==b.firstTime&&frames.back().snapshot.time==b.lastTime,"legacy history changed since indexing");
    if(d.legacyBarrier){size_t i=0;readArchiveCsvRange(d.location->path()/"barrier_trajectory.csv",b.legacyBarrierOffset,b.legacyBarrierLength,motionBlockFrames,[&](const CsvRow&r){require(i<frames.size()&&archiveInteger(r.at("trial_id"))==b.trialId&&archiveNumber(r.at("time"))==frames[i].snapshot.time,"legacy barrier time/trial mismatch");auto&barrier=frames[i++].snapshot.barrier;barrier.enabled=archiveInteger(r.at("enabled"))!=0;barrier.elastic=archiveInteger(r.at("elastic"))!=0;barrier.touched=archiveInteger(r.at("touched"))!=0;barrier.settled=archiveInteger(r.at("settled"))!=0;barrier.center=vector(r,"center_");barrier.rotation=rotation(r);const std::vector<std::pair<const char*,double*>> fields{{"displacement_m",&barrier.displacement},{"velocity_m_s",&barrier.velocity},{"support_force_N",&barrier.supportForce},{"contact_force_step_average_N",&barrier.contactForce},{"kinetic_J",&barrier.kineticEnergy},{"spring_J",&barrier.springEnergy},{"damper_loss_J",&barrier.dampingEnergy},{"support_work_residual_J",&barrier.supportWorkResidual},{"contact_impulse_Ns",&barrier.contactImpulse},{"max_abs_displacement_m",&barrier.maxDisplacement},{"peak_abs_support_N",&barrier.peakSupportForce},{"peak_abs_contact_substep_average_N",&barrier.peakContactForce}};for(auto field:fields)*field.second=archiveNumber(r.at(field.first));});require(i==frames.size(),"missing legacy barrier history frames");}return frames;
}
}
